		installed, ok := o.Packages[owner.Name]
		if !ok || installed.Version != owner.Version || installed.Release != owner.Release || installed.Arch != owner.Arch {
			// A different installed architecture or version is not represented
			// by the package selected for vulnerability reporting.
			continue
		}
		if !seen[owner.Name] {
			pkgNames = append(pkgNames, owner.Name)
			seen[owner.Name] = true
		}
	}
	if err := scanner.Err(); err != nil {
		return nil, xerrors.Errorf("Failed to read rpm -qf output: %w", err)
	}
	return pkgNames, nil
}

